AddDef.definition:
/// The same bytes with every line that starts with `from` starting with `to`
/// instead — an item moved between nesting levels keeps its inner structure and
/// drops or gains one level. Literal text is rebuilt chunk by chunk and every
/// range (chunks, local identifiers) follows its bytes. Lines inside multi-line
/// string literals move too; that is what a reviewer would expect to see.
pub fn reindent(&self, from: &[u8], to: &[u8]) -> crate::error::Result<Self> {
    if from == to {
        return Ok(self.clone());
    }
    let mut src = Vec::with_capacity(self.src.len());
    let mut map = vec![u32::MAX; self.src.len() + 1];
    let mut chunks = Vec::with_capacity(self.chunks.len());
    for chunk in &self.chunks {
        let Chunk::Literal(r) = chunk else {
            chunks.push(chunk.clone());
            continue;
        };
        let start = src.len() as u32;
        let mut at_line_start = r.start == 0 || self.src.get(r.start as usize - 1) == Some(&b'\n');
        let mut i = r.start as usize;
        while i < r.end as usize {
            map[i] = src.len() as u32;
            if at_line_start && !from.is_empty() && self.src[i..r.end as usize].starts_with(from) {
                src.extend_from_slice(to);
                for k in 1..from.len() {
                    map[i + k] = src.len() as u32;
                }
                i += from.len();
                at_line_start = false;
                continue;
            }
            if at_line_start && from.is_empty() && self.src[i] != b'\n' {
                src.extend_from_slice(to);
                map[i] = src.len() as u32;
            }
            let b = self.src[i];
            src.push(b);
            at_line_start = b == b'\n';
            i += 1;
        }
        map[r.end as usize] = src.len() as u32;
        chunks.push(Chunk::Literal(ByteRange {
            start,
            end: src.len() as u32,
        }));
    }
    let local_ranges = self
        .local_ranges
        .iter()
        .map(|(r, ident)| {
            (
                ByteRange {
                    start: map[r.start as usize],
                    end: map[r.end as usize],
                },
                ident.clone(),
            )
        })
        .collect();
    Self::new(src, chunks, local_ranges)
}

/// Re-indent `id` and everything nested in it from the level it had to the level of its
/// new parent (`None` = column 0), by the first code line's leading whitespace.
fn reindent_subtree(
    store: &dyn Store,
    snap: &mut Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
) -> Result<()> {
    let (rendered, _) = render_entity(snap, store, id, false)?;
    let lead = rendered.iter().take_while(|b| b.is_ascii_whitespace()).count();
    let line_start = rendered[..lead].iter().rposition(|b| *b == b'\n').map_or(0, |p| p + 1);
    let from = rendered[line_start..lead].to_vec();
    let to = new_parent
        .map(|p| sibling_indent(store, snap, p))
        .unwrap_or_default();
    if from == to {
        return Ok(());
    }
    for eid in subtree(snap, id) {
        let rec = &snap.entities[&eid];
        let bytes = store.get_bytes_blob(rec.bytes)?.reindent(&from, &to)?;
        let bytes_id = store.put_bytes_blob(&bytes)?;
        snap.entities.get_mut(&eid).unwrap().bytes = bytes_id;
    }
    Ok(())
}

EditDef.definition:
pub fn move_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
    ordinal: Option<u32>,
) -> Result<Snapshot> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    if let Some(p) = new_parent {
        if p == id || subtree(snap, id).contains(&p) {
            return Err(Error::Other("move would create a cycle".into()));
        }
        snap.entities.get(&p).ok_or(Error::NoSuchEntity(p))?;
    }
    let old_parent = rec.parent;
    let mut next = snap.clone();
    if let (None, Some(o)) = (new_parent, ordinal) {
        next.make_room_at_root(&rec.file, o, id);
    }
    next.reparent(id, new_parent, ordinal)?;
    if let Some(p) = new_parent {
        let file = next.entities[&p].file.clone();
        next.set_file(id, file, ordinal.unwrap_or(rec.ordinal))?;
    }
    if old_parent != new_parent {
        reindent_subtree(store, &mut next, id, new_parent)?;
    }
    if old_parent == new_parent {
        if let Some(p) = new_parent {
            let mut kids = child_ids_of(store, &next, p)?;
            kids.retain(|c| *c != id);
            let at = ordinal.unwrap_or(kids.len() as u32) as usize;
            kids.insert(at.min(kids.len()), id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
        if new_parent.is_none() {
            normalize_root_separators(store, &mut next, &rec.file)?;
        }
        return Ok(next);
    }
    if let Some(p) = old_parent {
        if next.entities.contains_key(&p) {
            let mut kids = child_ids_of(store, snap, p)?;
            kids.retain(|c| *c != id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
    }
    if let Some(p) = new_parent {
        let mut kids = child_ids_of(store, &next, p)?;
        kids.retain(|c| *c != id);
        let at = ordinal.unwrap_or(kids.len() as u32) as usize;
        kids.insert(at.min(kids.len()), id);
        apply_child_holes(store, &mut next, p, &kids)?;
    }
    reresolve_subtree(store, langs, &mut next, id)?;
    if old_parent.is_none() || new_parent.is_none() {
        let file = next.entities[&id].file.clone();
        normalize_root_separators(store, &mut next, &file)?;
        if rec.file != file {
            normalize_root_separators(store, &mut next, &rec.file)?;
        }
    }
    Ok(next)
}

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub enum Op {
    Rename {
        id: EntityId,
        new: String,
    },
    Move {
        id: EntityId,
        parent: Option<EntityId>,
        ordinal: Option<u32>,
    },
    Relocate {
        id: EntityId,
        file: RelPath,
        ordinal: u32,
    },
    Extract {
        id: EntityId,
        new_parent: Option<EntityId>,
        ordinal: u32,
    },
    Inline {
        id: EntityId,
    },
    AddDef {
        id: EntityId,
        parent: Option<EntityId>,
        ordinal: u32,
        definition: String,
        intent: Intent,
        /// Recorded target. Absent on ops from before this field existed
        /// (JSON) and on tests that still omit it; apply then uses the parent
        /// file, else the first tracked source file.
        #[serde(default)]
        file: Option<RelPath>,
    },
    Delete {
        id: EntityId,
        intent: Intent,
    },
    EditDef {
        id: EntityId,
        definition: String,
        intent: Intent,
    },
    Merge {
        other: ChangeId,
    },
    Undo,
    New {
        change: ChangeId,
    },
    Describe {
        msg: String,
    },
    /// Start a sibling change: parent is the current change's parent, then name it.
    Branch {
        name: String,
    },
    /// Working-copy reconciliation. Snapshot is `after.root` on the log entry so O5 can replay.
    Absorb,
    /// Resolution of conflict `conflict` (an index into the merge snapshot's list) by
    /// taking one side. Recorded as itself so replay reproduces the resolved snapshot.
    Resolve {
        conflict: u32,
        take: Take,
    },
    /// `svc op restore <n>`: return to the view as it stood right after op `n`.
    /// Distinct from `Undo` so the log names the verb.
    ///
    /// Last on purpose: postcard writes a variant as its index, so a variant added
    /// anywhere but the end re-labels every op already in every store (a `New` read
    /// back as `Restore`). `op_wire_format` pins the order.
    Restore {
        at: u64,
    },
}

crates/svc-core/tests/move_reindent.rs.Text:
//! An item moved between nesting levels is re-indented: a method extracted to file level
//! starts at column 0, a free fn moved into an impl gains the members' indentation.
//! Every line follows (bodies, attributes, doc comments), and the result reparses.
use std::collections::BTreeMap;

use svc_core::engine::{extract_hoist, lookup_name, move_def, render, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, RelPath};
use svc_core::store::MemStore;
use svc_core::Kind;

const SRC: &str = "\
pub struct B(Vec<u8>);

impl B {
    /// Length.
    #[inline]
    pub fn len(&self) -> usize {
        if self.0.is_empty() {
            0
        } else {
            self.0.len()
        }
    }
}

fn helper(x: u32) -> u32 {
    x + 1
}
";

fn setup() -> (MemStore, svc_core::Snapshot, RelPath) {
    let store = MemStore::new();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let snap = snapshot_files(&store, &rust_langs(), &files, None, ChangeId::new()).unwrap();
    (store, snap, path)
}

fn text(store: &MemStore, snap: &svc_core::Snapshot, path: &RelPath) -> String {
    String::from_utf8(render(snap, store, &rust_langs(), false).unwrap().files[path].clone()).unwrap()
}

#[test]
fn extracting_a_method_to_file_level_dedents_it() {
    let (store, snap, path) = setup();
    let len = lookup_name(&snap, "len").unwrap();
    let next = extract_hoist(&store, &rust_langs(), &snap, len, None, 2).unwrap();
    let out = text(&store, &next, &path);
    assert!(
        out.contains("\n/// Length.\n#[inline]\npub fn len(&self) -> usize {\n    if self.0.is_empty() {\n        0\n    } else {\n        self.0.len()\n    }\n}\n"),
        "{out}"
    );
    assert!(!out.contains("\n    /// Length."), "{out}");
    let reparsed = snapshot_files(
        &store,
        &rust_langs(),
        &BTreeMap::from([(path.clone(), out.into_bytes())]),
        Some(&next),
        ChangeId::new(),
    )
    .unwrap();
    assert_eq!(reparsed.entities.values().filter(|r| r.kind == Kind::Fn).count(), 2);
}

#[test]
fn moving_a_free_fn_into_an_impl_indents_it() {
    let (store, snap, path) = setup();
    let helper = lookup_name(&snap, "helper").unwrap();
    let imp = snap.entities.iter().find(|(_, r)| r.kind == Kind::Impl).map(|(id, _)| *id).unwrap();
    let next = move_def(&store, &rust_langs(), &snap, helper, Some(imp), None).unwrap();
    let out = text(&store, &next, &path);
    assert!(
        out.contains("    }\n\n    fn helper(x: u32) -> u32 {\n        x + 1\n    }\n}\n"),
        "{out}"
    );
    assert!(!out.contains("\nfn helper"), "{out}");
}

crates/svc-core/tests/op_wire_format.rs.Text:
//! The store writes `Op` with postcard, which encodes an enum variant as its index and
//! nothing else. Inserting a variant anywhere but at the end re-labels every op already
//! in every store: `Restore` added after `Undo` made a stored `New` read back as `Restore`
//! and the ops after it fail to decode ("Option discriminant that wasn't 0 or 1").
//! This table is the wire format. Add new variants at the end and extend the table.
use svc_core::ids::{ChangeId, EntityId, RelPath};
use svc_core::{Intent, Op, Take};

fn index_of(op: &Op) -> u8 {
    postcard::to_allocvec(op).unwrap()[0]
}

#[test]
fn op_variant_indices_are_append_only() {
    let id = EntityId::new();
    let table: [(Op, u8); 16] = [
        (Op::Rename { id, new: "n".into() }, 0),
        (Op::Move { id, parent: None, ordinal: None }, 1),
        (Op::Relocate { id, file: RelPath::new("a.rs").unwrap(), ordinal: 0 }, 2),
        (Op::Extract { id, new_parent: None, ordinal: 0 }, 3),
        (Op::Inline { id }, 4),
        (
            Op::AddDef { id, parent: None, file: None, ordinal: 0, definition: String::new(), intent: Intent::Fix },
            5,
        ),
        (Op::Delete { id, intent: Intent::Fix }, 6),
        (Op::EditDef { id, definition: String::new(), intent: Intent::Fix }, 7),
        (Op::Merge { other: ChangeId::new() }, 8),
        (Op::Undo, 9),
        (Op::New { change: ChangeId::new() }, 10),
        (Op::Describe { msg: String::new() }, 11),
        (Op::Branch { name: String::new() }, 12),
        (Op::Absorb, 13),
        (Op::Resolve { conflict: 0, take: Take::A }, 14),
        (Op::Restore { at: 0 }, 15),
    ];
    for (op, want) in &table {
        assert_eq!(index_of(op), *want, "{op:?} moved on the wire");
    }
}

#[test]
fn intent_and_take_indices_are_append_only() {
    for (i, intent) in [Intent::Refactor, Intent::Fix, Intent::Feature, Intent::Docs, Intent::Other(String::new())]
        .iter()
        .enumerate()
    {
        assert_eq!(postcard::to_allocvec(intent).unwrap()[0] as usize, i, "{intent:?}");
    }
    for (i, take) in [Take::A, Take::B, Take::Base].iter().enumerate() {
        assert_eq!(postcard::to_allocvec(take).unwrap()[0] as usize, i, "{take:?}");
    }
}
